import {capacityDefaults,capacityPreview} from './capacity.js?v=0.18.0';
export const LANES={pending:'New requests',tailored:'Keep tailored',standard:'Make standard',retired:'Decline / retire'};
export const REQUESTS=[
{id:'export',name:'A bespoke export',arrive:0,life:6,value:14,bonus:16,setup:8,standard:30,maint:5,retire:6,touches:['data']},
{id:'invoice',name:'Split invoices',arrive:0,life:2,value:18,bonus:12,setup:7,standard:34,maint:4,retire:5,touches:['billing']},
{id:'audit',name:'An audit feed',arrive:1,life:5,value:13,bonus:10,setup:10,standard:27,maint:5,retire:6,touches:['data','permissions']},
{id:'access',name:'A special access role',arrive:2,life:2,value:11,bonus:9,setup:6,standard:24,maint:4,retire:4,touches:['permissions']},
{id:'label',name:'Customer labels',arrive:2,life:4,value:10,bonus:8,setup:4,standard:25,maint:2,retire:3,touches:['branding']},
{id:'bundle',name:'A billing + usage bundle',arrive:3,life:3,value:21,bonus:12,setup:12,standard:35,maint:6,retire:8,touches:['billing','data']},
{id:'partner',name:'A partner export',arrive:4,life:2,value:15,bonus:7,setup:9,standard:28,maint:5,retire:5,touches:['data']},
{id:'branding',name:'A second branded workspace',arrive:4,life:2,value:9,bonus:7,setup:5,standard:24,maint:2,retire:3,touches:['branding']}];
export const active=s=>s==='tailored'||s==='standard';
export function create({finite=false}={}){return {...(finite?{capacity:capacityDefaults()}:{}),quarter:0,aging:.7,pairCost:3,entries:REQUESTS.filter(r=>r.arrive===0).map(r=>({id:r.id,status:'pending',plan:'pending',since:null})),history:[],value:0};}
export function request(id){const r=REQUESTS.find(r=>r.id===id);if(!r)throw Error('Unknown request.');return r;}
export function move(state,id,lane){if(state.quarter>=6)throw Error('This run is complete.');if(!Object.hasOwn(LANES,lane))throw Error('Unknown lane.');const next=structuredClone(state),entry=next.entries.find(e=>e.id===id);if(!entry)throw Error('That request is not visible yet.');if(entry.status==='retired')throw Error('A settled retirement cannot be reopened; use Undo or replay.');if(lane==='pending'&&entry.status!=='pending')throw Error('Existing work cannot return to new requests.');if(entry.status==='standard'&&lane==='tailored')throw Error('A standard cannot revert to a one-off implementation.');if(active(lane)&&!active(entry.status)&&state.quarter>=request(id).arrive+request(id).life)throw Error('This request has expired.');entry.plan=lane;return next;}
export function preview(state){let revenue=0,changeCost=0,maintenance=0,retirement=0,reuse=0;const pairs=[],cards=state.entries.map(e=>({...e,r:request(e.id)})),on=cards.filter(e=>active(e.plan));for(const e of cards){const r=e.r,newWork=!active(e.status)&&active(e.plan),age=e.since===null?0:state.quarter-e.since,alive=state.quarter<r.arrive+r.life;if(active(e.plan)){revenue+=(alive?r.value:0)+(newWork?r.bonus:0);maintenance+=e.plan==='standard'?r.maint*.4:r.maint+age*state.aging;if(newWork&&e.plan==='tailored'){const reusable=on.some(o=>o.id!==e.id&&o.plan==='standard'&&o.r.touches.some(t=>r.touches.includes(t)));const discount=reusable?Math.min(6,r.setup):0;changeCost+=r.setup-discount;reuse+=discount;}if(e.plan==='standard'&&e.status!=='standard')changeCost+=r.standard;}if(active(e.status)&&e.plan==='retired')retirement+=r.retire;}
for(let i=0;i<on.length;i++)for(let j=i+1;j<on.length;j++){const a=on[i],b=on[j],overlap=a.r.touches.filter(t=>b.r.touches.includes(t));if(overlap.length){const cost=state.pairCost*(a.plan==='standard'||b.plan==='standard'?1/3:1);maintenance+=cost;pairs.push({a:a.id,b:b.id,cost,overlap});}}
const totals={revenue,changeCost,maintenance,retirement,reuse,pairs,net:revenue-changeCost-maintenance-retirement,active:on.length};return state.capacity?{...totals,capacity:capacityPreview(state,totals,REQUESTS)}:totals;}
export function advance(state){if(state.quarter>=6)throw Error('This run is complete.');const totals=preview(state);if(totals.capacity&&!totals.capacity.feasible)throw Error(`This plan needs ${totals.capacity.required.toFixed(1)} effort-days; Q${state.quarter+1} has ${totals.capacity.budget.toFixed(1)}. Change the plan or its budget before settling.`);const next=structuredClone(state);next.history.push({quarter:state.quarter,...totals,decisions:state.entries.map(e=>({id:e.id,plan:e.plan}))});next.value+=totals.net;next.quarter++;next.entries=next.entries.map(e=>({...e,status:e.plan==='pending'?'retired':e.plan,plan:e.plan==='pending'?'retired':e.plan,since:e.since===null&&active(e.plan)?state.quarter:e.since}));for(const r of REQUESTS.filter(r=>r.arrive===next.quarter))next.entries.push({id:r.id,status:'pending',plan:'pending',since:null});return next;}
export function policy(state,kind){if(!['tailor','reuse'].includes(kind))throw Error('Unknown policy.');let next=structuredClone(state);for(const e of state.entries){const r=request(e.id),remaining=r.arrive+r.life-state.quarter;if(active(e.status)&&remaining<=0)next=move(next,e.id,'retired');else if(e.status==='pending')next=move(next,e.id,kind==='reuse'&&remaining>=3?'standard':'tailored');}return next;}
export function runPolicy(kind,settings={}){let s={...create(),...settings};while(s.quarter<6)s=advance(policy(s,kind));return s;}
export function configure(state,patch){const next={...state};for(const key of Object.keys(patch)){if(!['aging','pairCost'].includes(key)||!Number.isFinite(patch[key])||patch[key]<0||patch[key]>6)throw Error('Costs must be between 0 and 6.');next[key]=patch[key];}return next;}
